def _poly(x, d):
    return np.column_stack([np.prod(x[:, p], axis=1)
                            for p in combinations_with_replacement(range(x.shape[1]), d)]) if d else np.ones((len(x), 1))


def _quadratic_gram(x):
    f = np.column_stack([_poly(x, j) for j in range(3)])
